header.scrolled nav a { color: #44403c; }
nav a::after { content: ''; position: absolute; bottom: -2px; left: 0; width: 0; height: 2px; background: #1c1917; transition: width 0.3s; }
header.scrolled nav a::after { background: #1c1917; }
header:not(.scrolled) nav a::after { background: #fff; }
nav a:hover::after { width: 100%; }
.nav-cta { display: flex; align-items: center; gap: 0.4rem; padding: 0.625rem 1.25rem; background: linear-gradient(135deg, #22c55e, #10b981); color: #fff !important; border-radius: 1rem; font-weight: 600; font-size: 0.875rem; transition: all 0.3s; box-shadow: 0 4px 16px rgba(34,197,94,0.3); }
